      "hideWarnings": true
    }
  },
  "signals": [
    {
      "name": "svNow",
      "update": "length(data('sv_fresh')) ? data('sv_fresh')[0].nowb.buckets[0].from : 0"
    },
    {
      "name": "svInHours",
      "update": "utchours(svNow) >= 7 && utchours(svNow) < 19"
    },
    {
      "name": "svLast",
      "update": "length(data('sv_fresh')) ? data('sv_fresh')[0].last.value : null"
    },
    {
      "name": "svEstLast",
      "update": "length(data('sv_flow')) && data('sv_flow')[0].last.value ? data('sv_flow')[0].last.value : svNow"
    },
    {
      "name": "svAgeMin",
      "update": "isValid(svLast) ? (svNow - svLast) / 60000 : null"
    },
    {
      "name": "svCostLast",
      "update": "length(data('sv_cost')) ? data('sv_cost')[0].last.value : null"
    },
    {
      "name": "svCostLag",
      "update": "isValid(svCostLast) ? floor((floor(svNow / 86400000) * 86400000 - floor(svCostLast / 86400000) * 86400000) / 86400000) : null"
    },
    {
      "name": "svWorkers",
      "update": "length(data('sv_rs'))"
    },
    {
      "name": "svUsualProcs",
      "update": "length(data('sv_pr_usual'))"
    },
    {
      "name": "off_unmapped_rank",
      "update": "length(data('off_unmapped')) ? extent(pluck(data('off_unmapped'), 'rank'))[1] : 1"
    },
    {
      "name": "off_unmapped_n",
      "update": "length(data('off_unmapped'))"
    },
    {
      "name": "off_unmapped_detail",
      "update": "join(slice(pluck(data('off_unmapped'), 'txt'), 0, 2), '; ') + (length(data('off_unmapped')) > 2 ? '; +' + (length(data('off_unmapped')) - 2) + ' more' : '')"
    },
    {
      "name": "off_sla_rank",
      "update": "length(data('off_sla')) ? extent(pluck(data('off_sla'), 'rank'))[1] : 1"
    },
    {
      "name": "off_sla_n",
      "update": "length(data('off_sla'))"
    },
    {
      "name": "off_sla_detail",
      "update": "join(slice(pluck(data('off_sla'), 'txt'), 0, 2), '; ') + (length(data('off_sla')) > 2 ? '; +' + (length(data('off_sla')) - 2) + ' more' : '')"
    },
    {
      "name": "off_locks_rank",
      "update": "length(data('off_locks')) ? extent(pluck(data('off_locks'), 'rank'))[1] : 1"
    },
    {
      "name": "off_locks_n",
      "update": "length(data('off_locks'))"
    },
    {
      "name": "off_locks_detail",
      "update": "join(slice(pluck(data('off_locks'), 'txt'), 0, 2), '; ') + (length(data('off_locks')) > 2 ? '; +' + (length(data('off_locks')) - 2) + ' more' : '')"
    },
    {
      "name": "off_workers_rank",
      "update": "length(data('off_workers')) ? extent(pluck(data('off_workers'), 'rank'))[1] : 1"
    },
    {
      "name": "off_workers_n",
      "update": "length(data('off_workers'))"
    },
    {
      "name": "off_workers_detail",
      "update": "join(slice(pluck(data('off_workers'), 'txt'), 0, 2), '; ') + (length(data('off_workers')) > 2 ? '; +' + (length(data('off_workers')) - 2) + ' more' : '')"
    },
    {
      "name": "off_processes_rank",
      "update": "length(data('off_processes')) ? extent(pluck(data('off_processes'), 'rank'))[1] : 1"
    },
    {
      "name": "off_processes_n",
      "update": "length(data('off_processes'))"
    },
    {
      "name": "off_processes_detail",
      "update": "join(slice(pluck(data('off_processes'), 'txt'), 0, 2), '; ') + (length(data('off_processes')) > 2 ? '; +' + (length(data('off_processes')) - 2) + ' more' : '')"
    },
    {
      "name": "off_sys_spike_rank",
      "update": "length(data('off_sys_spike')) ? extent(pluck(data('off_sys_spike'), 'rank'))[1] : 1"
    },
    {
      "name": "off_sys_spike_n",
      "update": "length(data('off_sys_spike'))"
    },
    {
      "name": "off_sys_spike_detail",
      "update": "join(slice(pluck(data('off_sys_spike'), 'txt'), 0, 2), '; ') + (length(data('off_sys_spike')) > 2 ? '; +' + (length(data('off_sys_spike')) - 2) + ' more' : '')"
    },
    {
      "name": "off_new_reasons_rank",
      "update": "length(data('off_new_reasons')) ? extent(pluck(data('off_new_reasons'), 'rank'))[1] : 1"
    },
    {
      "name": "off_new_reasons_n",
      "update": "length(data('off_new_reasons'))"
    },
    {
