    {
      "name": "sv_pr",
      "source": "sv_flow",
      "transform": [
        {
          "type": "flatten",
          "fields": [
            "pr.buckets"
          ],
          "as": [
            "g"
          ]
        },
        {
          "type": "formula",
          "as": "name",
          "expr": "datum.g.key"
        },
        {
          "type": "formula",
          "as": "spoke",
          "expr": "length(datum.g.sp.buckets) ? datum.g.sp.buckets[0].key : ''"
        },
        {
          "type": "formula",
          "as": "a0",
          "expr": "datum.g.w.buckets.w0.a.value"
        },
        {
          "type": "formula",
          "as": "a1",
          "expr": "datum.g.w.buckets.w1.a.value"
        },
        {
          "type": "formula",
          "as": "a2",
          "expr": "datum.g.w.buckets.w2.a.value"
        },
        {
          "type": "formula",
          "as": "a3",
          "expr": "datum.g.w.buckets.w3.a.value"
        },
        {
          "type": "formula",
          "as": "a4",
          "expr": "datum.g.w.buckets.w4.a.value"
        },
        {
          "type": "formula",
          "as": "s0",
          "expr": "datum.g.w.buckets.w0.s.value"
        },
        {
          "type": "formula",
          "as": "ab",
          "expr": "datum.g.w.buckets.base.a.value"
        },
        {
          "type": "formula",
          "as": "sb",
          "expr": "datum.g.w.buckets.base.s.value"
        },
        {
          "type": "formula",
          "as": "usual",
          "expr": "(datum.a1 + datum.a2 + datum.a3 + datum.a4) / 4"
        },
        {
          "type": "formula",
          "as": "baseRate",
          "expr": "max(0.005, datum.ab ? datum.sb / datum.ab : 0)"
        },
        {
          "type": "formula",
          "as": "rate0",
          "expr": "datum.a0 ? datum.s0 / datum.a0 : 0"
        },
        {
          "type": "formula",
          "as": "silent",
          "expr": "datum.usual >= 10 && datum.a0 < datum.usual * 0.25 ? 'act' : datum.usual >= 10 && datum.a0 < datum.usual * 0.5 ? 'warn' : 'ok'"
        },
        {
          "type": "formula",
          "as": "spike",
          "expr": "datum.s0 >= 10 && datum.rate0 > 3 * datum.baseRate ? 'act' : datum.s0 >= 5 && datum.rate0 > 2 * datum.baseRate ? 'warn' : 'ok'"
        },
        {
          "type": "project",
          "fields": [
            "name",
            "spoke",
            "a0",
            "a1",
            "a2",
            "a3",
            "a4",
            "s0",
            "ab",
            "sb",
            "usual",
            "baseRate",
            "rate0",
            "silent",
            "spike"
          ]
        }
      ]
    },
