    {
      "name": "hub_raw",
      "url": {
        "index": "ia-workqueue-items",
        "body": {
          "size": 0,
          "query": {
            "bool": {
              "must": [
                "%dashboard_context-must_clause%",
                {
                  "term": {
                    "mapped": true
                  }
                },
                {
                  "range": {
                    "@timestamp": {
                      "gte": {
                        "%timefilter%": "max",
                        "shift": -696,
                        "unit": "hour"
                      },
                      "lte": {
                        "%timefilter%": "max"
                      },
                      "format": "epoch_millis"
                    }
                  }
                }
              ],
              "filter": [
                "%dashboard_context-filter_clause%"
              ],
              "must_not": [
                "%dashboard_context-must_not_clause%"
              ]
            }
          },
          "aggs": {
            "s": {
              "terms": {
                "field": "spoke.name",
                "size": 50
              },
              "aggs": {
                "cur": {
                  "filter": {
                    "range": {
                      "@timestamp": {
                        "gte": {
                          "%timefilter%": "max",
                          "shift": -24,
                          "unit": "hour"
                        },
                        "lte": {
                          "%timefilter%": "max"
                        },
                        "format": "epoch_millis"
                      }
                    }
                  },
                  "aggs": {
                    "a": {
                      "sum": {
                        "field": "n.attempt"
                      }
                    },
                    "c": {
                      "sum": {
                        "field": "n.completed"
                      }
                    },
                    "e": {
                      "sum": {
                        "field": "n.exception"
                      }
                    },
                    "s": {
                      "sum": {
                        "field": "n.system"
                      }
                    },
                    "hr": {
                      "date_histogram": {
                        "field": "@timestamp",
                        "fixed_interval": "1h",
                        "min_doc_count": 0,
                        "extended_bounds": {
                          "min": {
                            "%timefilter%": "max",
                            "shift": -23,
                            "unit": "hour"
                          },
                          "max": {
                            "%timefilter%": "max"
                          }
                        }
                      },
                      "aggs": {
                        "c": {
                          "sum": {
                            "field": "n.completed"
                          }
                        },
                        "e": {
                          "sum": {
                            "field": "n.exception"
                          }
                        }
                      }
                    }
                  }
                },
                "w": {
                  "filters": {
                    "filters": {
                      "w1": {
                        "range": {
                          "@timestamp": {
                            "gte": {
                              "%timefilter%": "max",
                              "shift": -192,
                              "unit": "hour"
                            },
                            "lte": {
                              "%timefilter%": "max",
                              "shift": -168,
                              "unit": "hour"
                            },
                            "format": "epoch_millis"
                          }
                        }
                      },
                      "w2": {
                        "range": {
                          "@timestamp": {
                            "gte": {
                              "%timefilter%": "max",
                              "shift": -360,
                              "unit": "hour"
                            },
                            "lte": {
                              "%timefilter%": "max",
                              "shift": -336,
                              "unit": "hour"
                            },
                            "format": "epoch_millis"
                          }
                        }
                      },
                      "w3": {
                        "range": {
                          "@timestamp": {
                            "gte": {
                              "%timefilter%": "max",
                              "shift": -528,
                              "unit": "hour"
                            },
                            "lte": {
                              "%timefilter%": "max",
                              "shift": -504,
                              "unit": "hour"
                            },
                            "format": "epoch_millis"
                          }
                        }
                      },
                      "w4": {
                        "range": {
                          "@timestamp": {
                            "gte": {
                              "%timefilter%": "max",
                              "shift": -696,
                              "unit": "hour"
                            },
                            "lte": {
                              "%timefilter%": "max",
                              "shift": -672,
                              "unit": "hour"
                            },
                            "format": "epoch_millis"
                          }
                        }
                      }
                    }
                  },
                  "aggs": {
                    "a": {
                      "sum": {
                        "field": "n.attempt"
                      }
                    }
                  }
                },
                "cost": {
                  "filter": {
                    "range": {
                      "@timestamp": {
                        "gte": {
                          "%timefilter%": "max",
                          "shift": -192,
                          "unit": "hour"
                        },
                        "lte": {
                          "%timefilter%": "max",
                          "shift": -24,
                          "unit": "hour"
                        },
                        "format": "epoch_millis"
                      }
                    }
                  },
                  "aggs": {
                    "ec": {
                      "sum": {
                        "field": "cost.estate_gbp"
                      }
                    },
                    "c": {
                      "sum": {
                        "field": "n.completed"
                      }
                    }
                  }
                }
              }
            }
          }
        }
      },
      "format": {
        "property": "aggregations.s.buckets"
      }
    },
    {
      "name": "hb_sv_pr",
      "source": "sv_pr",
      "transform": [
        {
          "type": "formula",
