        },
        {
          "type": "aggregate",
          "groupby": [
            "spoke"
          ],
          "ops": [
            "sum",
            "sum",
            "sum"
          ],
          "fields": [
            "pSilent",
            "pSpike",
            "pAct"
          ],
          "as": [
            "pSilent",
            "pSpike",
            "pAct"
          ]
        }
      ]
    },
    {
      "name": "hb_sv_q",
