        },
        {
          "type": "aggregate",
          "groupby": [
            "spoke"
          ],
          "ops": [
            "sum",
            "sum",
            "sum",
            "sum"
          ],
          "fields": [
            "waiting",
            "past",
            "soon",
            "stuck"
          ],
          "as": [
            "waiting",
            "past",
            "soon",
            "stuck"
          ]
