        },
        {
          "type": "formula",
          "as": "wAct",
          "expr": "datum.state === 'act' ? 1 : 0"
        },
        {
          "type": "aggregate",
          "groupby": [
            "spoke"
          ],
          "ops": [
            "sum",
            "sum"
          ],
          "fields": [
            "wQuiet",
            "wAct"
          ],
          "as": [
            "wQuiet",
            "wAct"
          ]
        }
      ]
    },
    {
      "name": "hubs",
      "source": "hub_raw",
      "transform": [
        {
          "type": "formula",
          "as": "spoke",
          "expr": "datum.key"
        },
        {
          "type": "formula",
          "as": "a0",
          "expr": "datum.cur.a.value"
        },
        {
          "type": "formula",
          "as": "c0",
          "expr": "datum.cur.c.value"
        },
        {
          "type": "formula",
          "as": "usual",
          "expr": "(datum.w.buckets.w1.a.value + datum.w.buckets.w2.a.value + datum.w.buckets.w3.a.value + datum.w.buckets.w4.a.value) / 4"
        },
        {
          "type": "formula",
          "as": "ratio",
          "expr": "datum.usual ? datum.a0 / datum.usual : null"
        },
        {
          "type": "formula",
          "as": "compl",
          "expr": "datum.a0 ? datum.c0 / datum.a0 : null"
        },
        {
          "type": "formula",
          "as": "tC",
          "expr": "(indexof(pluck(data('tg'), 'k'), 'spoke|' + datum.spoke + '|completionPct') >= 0 ? data('tg')[indexof(pluck(data('tg'), 'k'), 'spoke|' + datum.spoke + '|completionPct')].v : tgt_completionPct)"
        },
        {
          "type": "formula",
          "as": "ec7",
          "expr": "datum.cost.ec.value"
        },
        {
          "type": "formula",
          "as": "cpi",
          "expr": "datum.cost.c.value ? datum.ec7 / datum.cost.c.value : null"
        },
        {
          "type": "formula",
          "as": "tCost",
          "expr": "(indexof(pluck(data('tg'), 'k'), 'spoke|' + datum.spoke + '|costPerCase') >= 0 ? data('tg')[indexof(pluck(data('tg'), 'k'), 'spoke|' + datum.spoke + '|costPerCase')].v : tgt_costPerCase)"
        },
        {
          "type": "lookup",
          "from": "hb_sv_pr",
          "key": "spoke",
          "fields": [
            "spoke"
          ],
          "values": [
            "pSilent",
            "pSpike",
            "pAct"
          ],
          "default": 0
        },
        {
          "type": "lookup",
          "from": "hb_sv_q",
          "key": "spoke",
          "fields": [
            "spoke"
          ],
          "values": [
            "waiting",
            "past",
            "soon",
            "stuck"
          ],
          "default": 0
        },
        {
          "type": "lookup",
          "from": "hb_sv_rs",
          "key": "spoke",
          "fields": [
            "spoke"
          ],
          "values": [
            "wQuiet",
            "wAct"
          ],
          "default": 0
        },
        {
          "type": "formula",
          "as": "lowCompl",
          "expr": "isValid(datum.compl) && datum.a0 >= 30 && datum.compl < datum.tC"
        },
        {
          "type": "formula",
          "as": "highCost",
          "expr": "isValid(datum.cpi) && datum.cpi > datum.tCost"
        },
        {
          "type": "formula",
          "as": "lowWork",
          "expr": "isValid(datum.ratio) && datum.usual >= 10 && datum.ratio < 0.5"
        },
        {
          "type": "formula",
          "as": "status",
          "expr": "datum.past > 0 || datum.stuck > 0 || datum.pAct > 0 || datum.wAct > 0 ? 'act' : datum.soon > 0 || datum.pSilent + datum.pSpike + datum.wQuiet > 0 || datum.lowCompl || datum.highCost ? 'warn' : 'ok'"
        },
