      "transform": [
        {
          "type": "flatten",
          "fields": [
            "rs.buckets"
          ],
          "as": [
            "g"
          ]
        },
        {
          "type": "formula",
          "as": "name",
          "expr": "datum.g.key"
        },
        {
          "type": "formula",
          "as": "spoke",
          "expr": "length(datum.g.sp.buckets) ? datum.g.sp.buckets[0].key : ''"
        },
        {
          "type": "formula",
          "as": "last",
          "expr": "datum.g.last.value"
        },
        {
          "type": "formula",
          "as": "w0",
          "expr": "datum.g.w.buckets.w0.doc_count"
        },
        {
          "type": "formula",
          "as": "w1",
          "expr": "datum.g.w.buckets.w1.doc_count"
        },
        {
          "type": "formula",
          "as": "w2",
          "expr": "datum.g.w.buckets.w2.doc_count"
        },
        {
          "type": "formula",
          "as": "w3",
          "expr": "datum.g.w.buckets.w3.doc_count"
        },
        {
          "type": "formula",
          "as": "w4",
          "expr": "datum.g.w.buckets.w4.doc_count"
        },
        {
          "type": "formula",
          "as": "usual",
          "expr": "(datum.w1 + datum.w2 + datum.w3 + datum.w4) / 4"
        },
        {
          "type": "lookup",
          "from": "sv_vdist",
          "key": "name",
          "fields": [
            "name"
          ],
          "values": [
            "status"
          ],
          "as": [
            "vstatus"
          ]
        },
        {
          "type": "filter",
          "expr": "datum.vstatus !== 'retired' && (datum.last >= svNow - 604800000 || datum.usual >= 10)"
        },
        {
          "type": "formula",
          "as": "gapH",
          "expr": "(svEstLast - max(datum.last, floor(svNow / 86400000) * 86400000 + 25200000)) / 3600000"
        },
        {
          "type": "formula",
          "as": "gapX",
          "expr": "datum.usual / 12 * datum.gapH >= 5"
        },
        {
          "type": "formula",
          "as": "ageMin",
          "expr": "(svNow - datum.last) / 60000"
        },
        {
          "type": "formula",
          "as": "state",
          "expr": "datum.usual >= 10 && datum.w0 < datum.usual * 0.25 ? 'act' : svInHours && datum.gapX && datum.gapH > 4 ? 'act' : svInHours && datum.gapX && datum.gapH > 2 ? 'warn' : datum.usual >= 10 && datum.w0 < datum.usual * 0.5 ? 'warn' : 'ok'"
        },
        {
          "type": "formula",
          "as": "hours",
          "expr": "datum.g.h.t.buckets"
        },
        {
          "type": "project",
          "fields": [
            "name",
            "spoke",
            "last",
            "w0",
            "usual",
            "gapH",
            "ageMin",
            "state",
            "hours"
          ]
