      "source": "sv_flow",
      "transform": [
        {
          "type": "flatten",
          "fields": [
            "rs.buckets"
          ],
          "as": [
            "g"
          ]
        },
        {
          "type": "formula",
          "as": "name",
          "expr": "datum.g.key"
        },
        {
          "type": "formula",
          "as": "spoke",
          "expr": "length(datum.g.sp.buckets) ? datum.g.sp.buckets[0].key : ''"
        },
        {
          "type": "formula",
          "as": "last",
          "expr": "datum.g.last.value"
        },
        {
          "type": "formula",
          "as": "w0",
          "expr": "datum.g.w.buckets.w0.doc_count"
        },
        {
          "type": "formula",
          "as": "w1",
          "expr": "datum.g.w.buckets.w1.doc_count"
        },
        {
          "type": "formula",
          "as": "w2",
          "expr": "datum.g.w.buckets.w2.doc_count"
        },
        {
          "type": "formula",
          "as": "w3",
          "expr": "datum.g.w.buckets.w3.doc_count"
        },
        {
          "type": "formula",
          "as": "w4",
          "expr": "datum.g.w.buckets.w4.doc_count"
        },
        {
          "type": "formula",
          "as": "usual",
          "expr": "(datum.w1 + datum.w2 + datum.w3 + datum.w4) / 4"
        },
        {
          "type": "lookup",
          "from": "sv_vdist",
          "key": "name",
          "fields": [
            "name"
          ],
          "values": [
            "status"
          ],
          "as": [
            "vstatus"
          ]
        },
        {
          "type": "filter",
          "expr": "datum.vstatus !== 'retired' && (datum.last >= svNow - 604800000 || datum.usual >= 10)"
        },
        {
          "type": "formula",
          "as": "gapH",
          "expr": "(svEstLast - max(datum.last, floor(svNow / 86400000) * 86400000 + 25200000)) / 3600000"
        },
        {
          "type": "formula",
          "as": "gapX",
          "expr": "datum.usual / 12 * datum.gapH >= 5"
        },
        {
          "type": "formula",
          "as": "ageMin",
          "expr": "(svNow - datum.last) / 60000"
        },
        {
          "type": "formula",
          "as": "state",
          "expr": "datum.usual >= 10 && datum.w0 < datum.usual * 0.25 ? 'act' : svInHours && datum.gapX && datum.gapH > 4 ? 'act' : svInHours && datum.gapX && datum.gapH > 2 ? 'warn' : datum.usual >= 10 && datum.w0 < datum.usual * 0.5 ? 'warn' : 'ok'"
        },
        {
          "type": "formula",
          "as": "hours",
          "expr": "datum.g.h.t.buckets"
        },
        {
          "type": "project",
          "fields": [
            "name",
            "spoke",
            "last",
            "w0",
            "usual",
            "gapH",
            "ageMin",
            "state",
            "hours"
          ]
        }
      ]
    },
    {
      "name": "off_workers",
      "source": "sv_rs",
      "transform": [
        {
          "type": "filter",
          "expr": "datum.state !== 'ok'"
        },
        {
          "type": "formula",
          "as": "rank",
          "expr": "({'quiet': 0, 'ok': 1, 'warn': 2, 'act': 3})[datum.state]"
        },
        {
          "type": "formula",
          "as": "m",
          "expr": "datum.usual - datum.w0"
        },
        {
          "type": "formula",
          "as": "txt",
          "expr": "datum.name + ': last item ' + (datum.ageMin < 90 ? round(datum.ageMin) + ' min' : datum.ageMin < 2880 ? round(datum.ageMin / 60) + ' h' : round(datum.ageMin / 1440) + ' days') + ' ago, ' + datum.w0 + ' in 24h vs usual ' + round(datum.usual)"
        },
        {
          "type": "collect",
          "sort": {
            "field": [
              "rank",
              "m",
              "name"
            ],
            "order": [
              "descending",
              "descending",
              "ascending"
            ]
          }
        }
      ]
    },
    {
      "name": "sv_q",
      "source": "sv_pending",
      "transform": [
        {
          "type": "flatten",
          "fields": [
            "q.buckets"
          ],
          "as": [
            "g"
          ]
        },
        {
          "type": "formula",
          "as": "name",
          "expr": "datum.g.key"
        },
        {
          "type": "formula",
          "as": "spoke",
          "expr": "length(datum.g.sp.buckets) ? datum.g.sp.buckets[0].key : ''"
        },
        {
          "type": "formula",
          "as": "process",
          "expr": "length(datum.g.pr.buckets) ? datum.g.pr.buckets[0].key : ''"
        },
        {
          "type": "formula",
          "as": "waiting",
          "expr": "datum.g.live.doc_count"
        },
        {
          "type": "formula",
          "as": "deferred",
          "expr": "datum.g.doc_count - datum.g.live.doc_count"
        },
        {
          "type": "formula",
          "as": "ageMin",
          "expr": "datum.waiting ? (svNow - datum.g.live.oldest.value) / 60000 : 0"
        },
        {
          "type": "formula",
          "as": "stuck",
          "expr": "datum.g.stuck.doc_count"
        },
        {
          "type": "formula",
          "as": "lockMin",
          "expr": "datum.stuck ? (svNow - datum.g.stuck.oldest.value) / 60000 : 0"
        },
        {
          "type": "formula",
          "as": "past",
          "expr": "datum.g.live.past.doc_count"
        },
        {
          "type": "formula",
          "as": "soon",
          "expr": "datum.g.live.soon.doc_count"
        },
        {
          "type": "formula",
          "as": "state",
          "expr": "datum.past > 0 ? 'act' : datum.soon > 0 ? 'warn' : 'ok'"
        },
        {
          "type": "formula",
          "as": "lockState",
          "expr": "datum.stuck > 0 ? 'act' : 'ok'"
        },
        {
          "type": "project",
          "fields": [
            "name",
            "spoke",
            "process",
            "waiting",
            "deferred",
            "ageMin",
            "past",
            "soon",
            "stuck",
            "lockMin",
            "state",
            "lockState"
          ]
        }
      ]
    },
    {
      "name": "off_sla",
      "source": "sv_q",
      "transform": [
        {
          "type": "filter",
          "expr": "datum.state !== 'ok'"
        },
        {
          "type": "formula",
          "as": "rank",
          "expr": "({'quiet': 0, 'ok': 1, 'warn': 2, 'act': 3})[datum.state]"
        },
        {
          "type": "formula",
          "as": "m",
          "expr": "datum.past + datum.soon / 1000"
        },
        {
          "type": "formula",
          "as": "txt",
          "expr": "datum.name + ': ' + (datum.past ? datum.past + ' past SLA' : datum.soon + ' due within 2 h') + ', oldest ' + (datum.ageMin < 90 ? round(datum.ageMin) + ' min' : datum.ageMin < 2880 ? round(datum.ageMin / 60) + ' h' : round(datum.ageMin / 1440) + ' days')"
        },
        {
          "type": "collect",
          "sort": {
            "field": [
