  "config": {
    "background": "#FFFFFF",
    "padding": 0,
    "font": "Inter, 'Segoe UI', system-ui, -apple-system, sans-serif",
    "text": {
      "font": "Inter, 'Segoe UI', system-ui, -apple-system, sans-serif",
      "fill": "#0F4D43",
      "fontSize": 12
    },
    "axis": {
      "gridColor": "#E6E8E2",
      "labelFont": "'Roboto Mono', Menlo, Consolas, monospace",
      "labelFontSize": 10,
      "labelColor": "#5F6E69",
      "titleFont": "'Roboto Mono', Menlo, Consolas, monospace",
      "titleColor": "#5F6E69",
      "titleFontSize": 10,
      "titleFontWeight": 400,
      "domain": false,
      "ticks": false,
      "gridWidth": 1,
      "labelPadding": 6
    },
    "style": {
      "guide-label": {
        "font": "'Roboto Mono', Menlo, Consolas, monospace"
      }
    },
    "view": {
      "stroke": null
    },
    "kibana": {
      "renderer": "svg",
      "hideWarnings": true
    }
  },
  "signals": [
    {
      "name": "headerRight",
      "value": 0
    },
    {
      "name": "top",
      "value": 42
    },
    {
      "name": "cw",
      "update": "width - 32"
    },
    {
      "name": "ch",
      "update": "height - top - 16"
    },
    {
      "name": "whenBy",
      "value": "hour",
      "on": [
        {
          "events": "@seg_whenBy_0:click",
          "update": "'hour'"
        },
        {
          "events": "@seg_whenBy_1:click",
          "update": "'weekday'"
        }
      ]
    },
    {
      "name": "labelW",
      "update": "clamp(cw * 0.24, 150, 260)"
    },
    {
      "name": "totW",
      "value": 70
    },
    {
      "name": "nRows",
      "update": "length(data('wr'))"
    },
    {
      "name": "rowH",
      "update": "nRows ? clamp((ch - 34) / nRows, 14, 30) : 20"
    },
    {
      "name": "pickW",
      "on": [
        {
          "events": "@wh_label:click",
          "update": "kibanaAddFilter({'match_phrase': {'process.name': datum.name}}, 'ia-workqueue-items*')"
        }
      ]
    }
  ],
  "data": [
    {
      "name": "wh_raw",
      "url": {
        "%context%": true,
        "%timefield%": "@timestamp",
        "index": "ia-workqueue-items",
        "body": {
          "size": 0,
          "aggs": {
            "m": {
              "filter": {
                "term": {
                  "mapped": true
                }
              },
              "aggs": {
                "p": {
                  "terms": {
                    "field": "process.name",
                    "size": 20,
                    "order": {
                      "w": "desc"
                    }
                  },
                  "aggs": {
                    "w": {
                      "sum": {
                        "field": "worktime_sec"
                      }
                    },
                    "hr": {
                      "terms": {
                        "field": "outcome_hour",
                        "size": 24
                      },
                      "aggs": {
                        "w": {
                          "sum": {
                            "field": "worktime_sec"
                          }
                        }
                      }
                    },
                    "dw": {
                      "terms": {
                        "field": "outcome_weekday",
                        "size": 7
                      },
                      "aggs": {
                        "w": {
                          "sum": {
                            "field": "worktime_sec"
                          }
                        }
                      }
                    }
                  }
                }
              }
            }
          }
        }
      },
      "format": {
        "property": "aggregations.m.p.buckets"
      }
    },
    {
      "name": "wr",
      "source": "wh_raw",
      "transform": [
        {
          "type": "formula",
          "as": "name",
          "expr": "datum.key"
        },
        {
          "type": "formula",
          "as": "tot",
          "expr": "datum.w.value * 0.0002777777777777778"
        },
        {
          "type": "window",
          "ops": [
            "row_number"
          ],
          "as": [
            "ri"
          ]
        }
      ]
    },
    {
      "name": "wc",
      "source": "wr",
      "transform": [
        {
          "type": "formula",
          "as": "bk",
          "expr": "whenBy === 'hour' ? datum.hr.buckets : datum.dw.buckets"
        },
        {
          "type": "flatten",
          "fields": [
            "bk"
          ],
          "as": [
            "b"
          ]
        },
        {
          "type": "formula",
          "as": "col",
          "expr": "datum.b.key"
        },
        {
          "type": "formula",
          "as": "v",
          "expr": "datum.b.w.value * 0.0002777777777777778"
        },
        {
          "type": "project",
          "fields": [
            "name",
            "ri",
            "col",
            "v",
            "tot"
          ]
        }
      ]
    },
    {
      "name": "wcols",
      "transform": [
        {
          "type": "sequence",
          "start": 0,
          "stop": 24,
          "as": "i"
        },
        {
          "type": "formula",
          "as": "col",
          "expr": "whenBy === 'hour' ? datum.i : datum.i + 1"
        },
        {
          "type": "filter",
          "expr": "whenBy === 'hour' || datum.i < 7"
        }
      ]
    },
    {
      "name": "wmax",
      "source": "wc",
      "transform": [
        {
          "type": "aggregate",
          "ops": [
            "max"
          ],
          "fields": [
            "v"
          ],
          "as": [
            "m"
          ]
        }
      ]
    }
  ],
  "scales": [
    {
      "name": "wx",
      "type": "band",
      "domain": {
        "data": "wcols",
        "field": "col",
        "sort": true
      },
      "range": [
        0,
        {
          "signal": "cw - labelW - totW"
        }
      ],
      "paddingInner": 0.06
    }
  ],
  "marks": [
    {
      "type": "text",
      "name": "frame_title",
      "encode": {
        "update": {
          "x": {
            "value": 16
          },
          "y": {
            "value": 18
          },
          "baseline": {
            "value": "top"
          },
          "font": {
            "value": "'Roboto Mono', Menlo, Consolas, monospace"
          },
          "fontSize": {
            "value": 11
          },
          "fontWeight": {
            "value": 600
          },
          "fill": {
            "value": "#0F4D43"
          },
          "text": {
            "signal": "'WHEN THE WORK RUNS'"
          },
          "limit": {
            "signal": "width - 32"
          }
        }
      }
    },
    {
      "type": "text",
      "encode": {
        "update": {
          "x": {
            "signal": "16 + length('WHEN THE WORK RUNS') * 6.9 + 10"
          },
          "y": {
            "value": 17
          },
          "baseline": {
            "value": "top"
          },
          "font": {
            "value": "Inter, 'Segoe UI', system-ui, -apple-system, sans-serif"
          },
          "fontSize": {
            "value": 12
          },
          "fill": {
            "value": "#5F6E69"
          },
          "text": {
            "signal": "'Bot hours by process and ' + (whenBy === 'hour' ? 'hour of day (UTC)' : 'day of week') + ' · pick a worker in the Digital worker control to see its day'"
          },
          "limit": {
            "signal": "width - 42 - length('WHEN THE WORK RUNS') * 6.9 - 0 - headerRight"
          }
        }
      }
    },
    {
      "type": "group",
      "encode": {
        "update": {
          "x": {
            "signal": "16 + labelW"
          },
          "y": {
            "signal": "top + 20"
          },
          "width": {
            "signal": "cw - labelW - totW"
          },
          "height": {
            "signal": "rowH * nRows"
          }
        }
      },
      "marks": [
        {
          "type": "text",
          "from": {
            "data": "wcols"
          },
          "encode": {
            "update": {
              "x": {
                "scale": "wx",
                "field": "col",
                "band": 0.5
              },
              "y": {
                "value": -6
              },
              "align": {
                "value": "center"
              },
              "font": {
                "value": "'Roboto Mono', Menlo, Consolas, monospace"
              },
              "fontSize": {
                "value": 10
              },
              "fill": {
                "value": "#5F6E69"
              },
              "text": {
                "signal": "whenBy === 'hour' ? pad('' + datum.col, 2, '0', 'left') : ['Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat', 'Sun'][datum.col - 1]"
              }
            }
          }
        },
        {
          "type": "rect",
          "from": {
            "data": "wc"
          },
          "encode": {
            "update": {
              "x": {
                "scale": "wx",
                "field": "col"
              },
              "width": {
                "scale": "wx",
                "band": 1
              },
              "y": {
                "signal": "(datum.ri - 1) * rowH + 1"
              },
              "height": {
                "signal": "rowH - 2"
              },
              "cornerRadius": {
                "value": 3
              },
              "fill": {
                "value": "#0F4D43"
              },
              "fillOpacity": {
                "signal": "length(data('wmax')) && data('wmax')[0].m ? 0.06 + 0.86 * datum.v / data('wmax')[0].m : 0"
              },
              "tooltip": {
                "signal": "{'': datum.name, 'When': whenBy === 'hour' ? pad('' + datum.col, 2, '0', 'left') + ':00 UTC' : ['Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat', 'Sun'][datum.col - 1], 'Bot hours': format(datum.v, ',.1f'), 'Share of its total': (isValid((datum.v / datum.tot)) && isFinite((datum.v / datum.tot)) ? format((datum.v / datum.tot) * 100, '.1f') + '%' : '–')}"
              }
            }
          }
        }
      ]
    },
    {
      "type": "text",
      "name": "wh_label",
      "from": {
        "data": "wr"
      },
      "encode": {
        "update": {
          "x": {
            "value": 16
          },
          "y": {
            "signal": "top + 20 + (datum.ri - 0.5) * rowH"
          },
          "baseline": {
            "value": "middle"
          },
          "font": {
            "value": "Inter, 'Segoe UI', system-ui, -apple-system, sans-serif"
          },
          "fontSize": {
            "value": 12
          },
          "fill": {
            "value": "#0F4D43"
          },
          "text": {
            "field": "name"
          },
          "limit": {
            "signal": "labelW - 10"
          },
          "cursor": {
            "value": "pointer"
          },
          "tooltip": {
            "signal": "'Click to filter to ' + datum.name"
          }
        }
      }
    },
    {
      "type": "text",
      "from": {
        "data": "wr"
      },
      "encode": {
        "update": {
          "x": {
            "signal": "16 + cw"
          },
          "y": {
            "signal": "top + 20 + (datum.ri - 0.5) * rowH"
          },
          "align": {
            "value": "right"
          },
          "baseline": {
            "value": "middle"
          },
          "font": {
            "value": "'Roboto Mono', Menlo, Consolas, monospace"
          },
          "fontSize": {
            "value": 11
          },
          "fontWeight": {
            "value": 600
          },
          "fill": {
            "value": "#0F4D43"
          },
          "text": {
