          "expr": "datum.ref ? datum.ref.spokeColor : '#5F6E69'"
        },
        {
          "type": "formula",
          "as": "queue",
          "expr": "datum.ref ? datum.ref.queue : ''"
        },
        {
          "type": "formula",
          "as": "proposition",
          "expr": "datum.ref ? datum.ref.proposition : ''"
        },
        {
          "type": "formula",
          "as": "slaHours",
          "expr": "datum.ref ? datum.ref.slaHours : null"
        }
      ]
    },
    {
      "name": "pos",
      "source": "bp",
      "transform": [
        {
          "type": "formula",
          "as": "net",
          "expr": "datum.gb - datum.ec"
        },
        {
          "type": "filter",
          "expr": "datum.net > 0"
        },
        {
          "type": "collect",
          "sort": {
            "field": "net",
            "order": "descending"
          }
        },
        {
          "type": "window",
          "ops": [
            "row_number",
            "sum"
          ],
          "fields": [
            null,
            "net"
          ],
          "as": [
            "r",
            "cum"
          ]
        }
      ]
    },
    {
      "name": "postot",
      "source": "pos",
      "transform": [
        {
          "type": "aggregate",
          "ops": [
            "sum",
            "count",
            "max"
          ],
          "fields": [
            "net",
            "net",
            "net"
          ],
          "as": [
            "total",
            "n",
            "top"
          ]
        }
      ]
    },
    {
      "name": "thr",
      "source": "pos",
      "transform": [
        {
          "type": "filter",
          "expr": "datum.cum - datum.net < 0.8 * posTotal"
        },
        {
          "type": "aggregate",
          "ops": [
            "count"
          ],
          "as": [
            "k"
          ]
        }
      ]
    },
    {
      "name": "shown",
      "source": "pos",
      "transform": [
        {
          "type": "filter",
          "expr": "datum.r * lgH <= ch - 24"
        },
        {
          "type": "formula",
          "as": "core",
          "expr": "datum.r <= thrK"
        }
      ]
    }
  ],
  "marks": [
    {
      "type": "text",
      "name": "frame_title",
      "encode": {
        "update": {
          "x": {
            "value": 16
          },
          "y": {
            "value": 18
          },
          "baseline": {
            "value": "top"
          },
