        {
          "type": "formula",
          "as": "gb",
          "expr": "datum['gb'].value"
        },
        {
          "type": "formula",
          "as": "ec",
          "expr": "datum['ec'].value"
        },
        {
          "type": "formula",
          "as": "c",
          "expr": "datum['c'].value"
        },
        {
          "type": "formula",
          "as": "rw",
          "expr": "datum['rw'].value"
        },
        {
          "type": "lookup",
