        }
      ]
    },
    {
      "name": "loss_shown",
      "source": "loss",
      "transform": [
        {
          "type": "window",
          "ops": [
            "row_number"
          ],
          "as": [
            "k"
          ]
        },
        {
          "type": "filter",
          "expr": "datum.k * rvH <= ch + 4"
        }
      ]
    }
